package ai.taskforge.config;
import ai.taskforge.domain.*; import ai.taskforge.knowledge.KnowledgeService; import ai.taskforge.repo.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder; import java.time.*;
@Configuration public class DemoData { @Bean CommandLineRunner seed(UserRepository users,ProjectRepository projects,TaskRepository tasks,DocumentRepository documents,KnowledgeService knowledge,WorkflowRepository workflows,WorkflowStepRepository workflowSteps,PasswordEncoder passwords){return args->{if(users.count()==0){var admin=users.save(new AppUser("admin@taskforge.demo",passwords.encode("DemoPass123!"),"Avery Admin",Role.ADMIN));var manager=users.save(new AppUser("manager@taskforge.demo",passwords.encode("DemoPass123!"),"Morgan Manager",Role.MANAGER));var dev=users.save(new AppUser("sam@taskforge.demo",passwords.encode("DemoPass123!"),"Sam Developer",Role.EMPLOYEE));users.save(new AppUser("riley@taskforge.demo",passwords.encode("DemoPass123!"),"Riley QA",Role.EMPLOYEE));users.save(new AppUser("jordan@taskforge.demo",passwords.encode("DemoPass123!"),"Jordan Operations",Role.EMPLOYEE));var p=projects.save(new Project("Acme platform rollout","Client onboarding and production readiness"));var review=new Task("Review Acme deployment checklist","Confirm security and rollback requirements.",manager);review.update("Review Acme deployment checklist","Confirm security and rollback requirements.",TaskStatus.IN_REVIEW,Priority.HIGH,LocalDate.now().plusDays(1),manager,p,"Deployment",82);tasks.save(review);var deploy=new Task("Deploy Acme production release","Deploy after checklist approval.",admin);deploy.update("Deploy Acme production release","Deploy after checklist approval.",TaskStatus.BLOCKED,Priority.CRITICAL,LocalDate.now().plusDays(2),dev,p,"Deployment",94);deploy.addDependency(review);tasks.save(deploy);var invoice=new Task("Reconcile September invoice","Validate purchase order and payment terms.",manager);invoice.update("Reconcile September invoice","Validate purchase order and payment terms.",TaskStatus.TODO,Priority.MEDIUM,LocalDate.now().plusDays(5),dev,p,"Finance",60);tasks.save(invoice);var guide=documents.save(new Document("Production deployment procedure.txt","text/plain","Production deployments require a manager approval, a completed security checklist, a rollback plan, and QA sign-off. After approval, the release owner deploys during the approved change window and records the outcome in the deployment log.",manager));knowledge.index(guide);}if(workflows.count()==0){var manager=users.findByRole(Role.MANAGER).stream().findFirst().orElseThrow();var workflow=workflows.save(new Workflow("Production Deployment","Controlled production release from review through deployment.",manager));workflowSteps.save(new WorkflowStep(workflow,1,"Initial deployment review","MANAGER",false,24));workflowSteps.save(new WorkflowStep(workflow,2,"Manager approval","MANAGER",true,24));workflowSteps.save(new WorkflowStep(workflow,3,"Production deployment","EMPLOYEE",false,8));}};} }
